// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    keepMyEther c;

    function setUp() public { c = new keepMyEther(); }

    function testFuzz_property(uint256 x, uint256 y) public {
        x = bound(x, 1 ether, 1000 ether);
        y = bound(y, 1 ether, 1000 ether);

        Attacker a = new Attacker(c);
        address victim = address(0xB0b);

        // attacker deposits x via the fallback
        vm.deal(address(a), x);
        a.deposit(x);
        // an unrelated victim deposits y via the fallback
        vm.deal(victim, y);
        vm.prank(victim);
        (bool okDep,) = address(c).call{value: y}("");
        assertTrue(okDep);

        // attacker withdraws once; its receive() re-enters withdraw
        a.attack();

        // GENERAL RULE: after any withdrawal(s), the contract still holds the
        // non-withdrawing victim's deposit y (reentrancy cannot steal it).
        // Reference: outer withdraw sends only x, inner re-entrant withdraw is
        // blocked by the lock, so address(c).balance == y.
        // Mutant: the unlocked inner withdraw sends x a second time out of the
        // victim's deposit, so address(c).balance == 0.
        assertEq(address(c).balance, y, "victim deposit must survive a re-entrant withdraw attempt");
    }
}

contract Attacker {
    keepMyEther c;
    bool reentered;

    constructor(keepMyEther _c) { c = _c; }

    function deposit(uint256 amt) external {
        (bool s, ) = address(c).call{value: amt}("");
        require(s);
    }

    function attack() external {
        (bool s, ) = address(c).call(abi.encodeWithSignature("withdraw()"));
        require(s);
    }

    receive() external payable {
        if (!reentered) {
            reentered = true;
            (bool s, ) = address(c).call(abi.encodeWithSignature("withdraw()"));
            s; // ignore result so the outer withdrawal still completes
        }
    }
}
